package com.example.starter.ventilation;

/**
 * 设备类型。
 */
public enum DeviceType {
    /** 风机 */
    FAN,
    /** 风阀 */
    DAMPER
}

package com.example.starter.ventilation;

/**
 * 设备指令动作。
 */
public enum DeviceAction {
    /** 开风阀 */
    OPEN,
    /** 关风阀 */
    CLOSE,
    /** 启动风机 */
    START,
    /** 停止风机 */
    STOP
}

package com.example.starter.ventilation;

/**
 * 火灾模式会话状态。
 */
public enum ModeStatus {
    /** 激活中：指令序列下发/到位阶段 */
    ACTIVE,
    /** 复位中：火警解除，按逆序复位 */
    RESETTING,
    /** 复位完成：复位指令全部到位，归档前不接受新的激活 */
    RESET_COMPLETE,
    /** 已归档：终态 */
    ARCHIVED
}

package com.example.starter.ventilation;

/**
 * 设备指令执行状态。
 */
public enum CommandStatus {
    /** 待下发（前序设备未到位） */
    PENDING,
    /** 已下发，等待到位反馈 */
    SENT,
    /** 已到位 */
    ACKED,
    /** 两次下发均超时，判设备故障 */
    FAULT
}

package com.example.starter.ventilation;

/**
 * 幂等请求类型。
 */
public enum RequestType {
    /** 火灾模式激活 */
    ACTIVATE,
    /** 火警解除复位 */
    RESET,
    /** 模式归档 */
    ARCHIVE,
    /** 设备到位反馈 */
    FEEDBACK
}

package com.example.starter.ventilation;

import java.time.Clock;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicReference;

/**
 * 可控时钟：生产环境使用系统 UTC 时钟，测试环境可推进/固定时间，
 * 以便确定性验证 60 秒恰超时等时间边界。
 */
public class MutableClock {

    private final AtomicReference<Clock> clock = new AtomicReference<>(Clock.systemUTC());

    /** 当前 epoch 毫秒。 */
    public long nowMillis() {
        return Instant.now(clock.get()).toEpochMilli();
    }

    /** 替换底层时钟（测试用）。 */
    public void setClock(Clock newClock) {
        clock.set(newClock);
    }

    /** 恢复系统时钟。 */
    public void reset() {
        clock.set(Clock.systemUTC());
    }
}

package com.example.starter.ventilation;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 通风联动服务参数。
 *
 * @param feedbackTimeoutSeconds 到位反馈超时秒数，下发时刻起算，恰满 60 秒判超时
 * @param scheduler              后台超时巡检调度配置
 */
@ConfigurationProperties(prefix = "ventilation")
public record VentilationProperties(
        long feedbackTimeoutSeconds,
        Scheduler scheduler
) {
    /**
     * @param enabled      是否启用后台巡检（测试中可关闭，改用显式触发）
     * @param fixedDelayMs 巡检间隔毫秒
     */
    public record Scheduler(boolean enabled, long fixedDelayMs) {
    }
}

package com.example.starter.ventilation;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 通风联动服务 Bean 装配。
 */
@Configuration
@EnableConfigurationProperties(VentilationProperties.class)
public class VentilationConfig {

    @Bean
    public MutableClock mutableClock() {
        return new MutableClock();
    }
}

