package com.example.starter.ventilation.web;

import com.example.starter.ventilation.domain.EventLogRow;
import com.example.starter.ventilation.repo.EventLogRepository;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * 事件流水查询：全部指令、反馈与状态迁移按自增 id 有序可查。
 */
@RestController
@RequestMapping("/api/ventilation/events")
public class EventLogController {

    private static final int DEFAULT_LIMIT = 100;
    private static final int MAX_LIMIT = 500;

    private final EventLogRepository events;

    public EventLogController(EventLogRepository events) {
        this.events = events;
    }

    /** 全量分页查询，?afterId=0&amp;limit=100。 */
    @GetMapping
    public EventLogView.Page page(@RequestParam(defaultValue = "0") long afterId,
                                  @RequestParam(defaultValue = "100") int limit) {
        int safeLimit = Math.min(Math.max(limit, 1), MAX_LIMIT);
        List<EventLogRow> rows = events.findPage(afterId, safeLimit + 1);
        boolean hasMore = rows.size() > safeLimit;
        if (hasMore) {
            rows = rows.subList(0, safeLimit);
        }
        List<EventLogView> views = rows.stream()
                .map(r -> new EventLogView(r.id(), r.eventType(), r.sessionId(), r.zoneCode(),
                        r.requestId(), r.detail(), r.eventTime()))
                .toList();
        return new EventLogView.Page(views, hasMore);
    }
}

package com.example.starter.ventilation.schedule;

import com.example.starter.ventilation.VentilationProperties;
import com.example.starter.ventilation.service.VentilationModeService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;

/**
 * 到位反馈超时巡检调度：周期扫描已下发且满 60 秒未到位的指令，
 * 触发重发一次 / 二次超时转故障升级。测试中可用 ventilation.scheduler.enabled=false 关闭。
 */
@Configuration
@EnableScheduling
@ConditionalOnProperty(prefix = "ventilation.scheduler", name = "enabled", matchIfMissing = true)
public class TimeoutScanScheduler {

    private static final Logger log = LoggerFactory.getLogger(TimeoutScanScheduler.class);

    private final VentilationModeService service;
    private final VentilationProperties properties;

    public TimeoutScanScheduler(VentilationModeService service, VentilationProperties properties) {
        this.service = service;
        this.properties = properties;
    }

    /** 固定间隔巡检；间隔由 ventilation.scheduler.fixed-delay-ms 配置。 */
    @Scheduled(fixedDelayString = "${ventilation.scheduler.fixed-delay-ms:1000}")
    public void scan() {
        try {
            int processed = service.scanTimeouts();
            if (processed > 0) {
                log.info("超时巡检处理指令数：{}", processed);
            }
        } catch (Exception e) {
            log.warn("超时巡检失败：{}", e.getMessage());
        }
    }
}

