private void ack(long sessionId, String deviceCode, String requestId) {
    FeedbackResponse r = service.feedback(requestId, sessionId, deviceCode, "IN_POSITION");
    assertTrue(r.accepted(), () -> "反馈应被采纳：" + r.note());
}

