assertEquals("ARCHIVED", jdbc.queryForObject(
        "SELECT status FROM mode_session WHERE id=?", String.class, sid));
assertNull(jdbc.queryForObject(
        "SELECT id FROM zone_activation_lock WHERE zone_code='ZONE_C'", Long.class));

